// ESP32 — PIR Bewegungsmelder
#define PIR_PIN 13
#define LED_PIN 12

int lastState = LOW;

void setup() {
  Serial.begin(115200);
  pinMode(PIR_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  Serial.println("Aufwaermphase: bitte 30 Sekunden warten...");
  delay(30000);
  Serial.println("Bereit!");
}

void loop() {
  int motion = digitalRead(PIR_PIN);
  digitalWrite(LED_PIN, motion);
  if (motion != lastState) {
    if (motion == HIGH) {
      Serial.println("Bewegung erkannt!");
    } else {
      Serial.println("Keine Bewegung.");
    }
    lastState = motion;
  }
}
